import{_ as n,c as i,o as a,ag as r}from"./chunks/framework.DfL_BkQ-.js";const c=JSON.parse('{"title":"Nutzungsbedingungen","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/terms.md","filePath":"de/guide/terms.md","lastUpdated":1794112334000}'),t={name:"de/guide/terms.md"};function u(s,e,d,l,h,g){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="nutzungsbedingungen" tabindex="-1">Nutzungsbedingungen <a class="header-anchor" href="#nutzungsbedingungen" aria-label="Permalink to &quot;Nutzungsbedingungen&quot;">​</a></h1><h2 id="annahme-der-bedingungen" tabindex="-1">Annahme der Bedingungen <a class="header-anchor" href="#annahme-der-bedingungen" aria-label="Permalink to &quot;Annahme der Bedingungen&quot;">​</a></h2><p>Durch das Herunterladen, Installieren oder Verwenden von Nicasa („die App“) erklärst du dich mit diesen Nutzungsbedingungen („Bedingungen“) einverstanden. Wenn du mit diesen Bedingungen nicht einverstanden bist, verwende die App nicht.</p><h2 id="beschreibung-des-dienstes" tabindex="-1">Beschreibung des Dienstes <a class="header-anchor" href="#beschreibung-des-dienstes" aria-label="Permalink to &quot;Beschreibung des Dienstes&quot;">​</a></h2><p>Nicasa ist ein Desktop-Bildbetrachter und ein Screenshot-Tool für macOS, das Folgendes bietet:</p><ul><li>Funktionen zum Ansehen und Durchstöbern von Bildern</li><li>Screenshot- und Bildschirmaufnahmefunktionen</li><li>KI-gestützte Bildbearbeitungswerkzeuge</li><li>Chrome-Browsererweiterung zum Extrahieren von Webbildern</li><li>Transparenter Overlay-Modus für Designarbeit</li></ul><h2 id="lizenz-und-nutzungsrechte" tabindex="-1">Lizenz und Nutzungsrechte <a class="header-anchor" href="#lizenz-und-nutzungsrechte" aria-label="Permalink to &quot;Lizenz und Nutzungsrechte&quot;">​</a></h2><h3 id="mac-app-store-version" tabindex="-1">Mac App Store-Version <a class="header-anchor" href="#mac-app-store-version" aria-label="Permalink to &quot;Mac App Store-Version&quot;">​</a></h3><ul><li>erfordert einen einmaligen Kauf von 4,99 $</li><li>lizenziert für die Nutzung auf Geräten, die mit deiner Apple-ID verknüpft sind</li><li>mit Familienfreigabe kompatibel</li></ul><h3 id="chrome-erweiterung" tabindex="-1">Chrome-Erweiterung <a class="header-anchor" href="#chrome-erweiterung" aria-label="Permalink to &quot;Chrome-Erweiterung&quot;">​</a></h3><ul><li>kostenlos herunterladbar und nutzbar</li><li>unterliegt den Bedingungen des Chrome Web Store</li></ul><h2 id="pflichten-der-nutzer" tabindex="-1">Pflichten der Nutzer <a class="header-anchor" href="#pflichten-der-nutzer" aria-label="Permalink to &quot;Pflichten der Nutzer&quot;">​</a></h2><p>Du erklärst dich damit einverstanden:</p><ul><li>die App nur für rechtmäßige Zwecke zu nutzen</li><li>nicht zu versuchen, die App zurückzuentwickeln, zu dekompilieren oder zu verändern</li><li>Rechte am geistigen Eigentum zu respektieren</li><li>die für die Funktion der App nötigen Systemberechtigungen zu erteilen</li><li>die App nicht zur Verletzung von Gesetzen oder Vorschriften zu nutzen</li></ul><h2 id="datenschutz-und-daten" tabindex="-1">Datenschutz und Daten <a class="header-anchor" href="#datenschutz-und-daten" aria-label="Permalink to &quot;Datenschutz und Daten&quot;">​</a></h2><p>Informationen zur Datenerfassung und zu unseren Datenschutzpraktiken findest du in unserer <a href="/de/guide/privacy.html">Datenschutzerklärung</a>.</p><h2 id="haftungsausschlusse" tabindex="-1">Haftungsausschlüsse <a class="header-anchor" href="#haftungsausschlusse" aria-label="Permalink to &quot;Haftungsausschlüsse&quot;">​</a></h2><h3 id="keine-gewahrleistung" tabindex="-1">Keine Gewährleistung <a class="header-anchor" href="#keine-gewahrleistung" aria-label="Permalink to &quot;Keine Gewährleistung&quot;">​</a></h3><p>Die App wird „wie besehen“ ohne jegliche Gewährleistung bereitgestellt. Der Entwickler schließt alle ausdrücklichen oder stillschweigenden Gewährleistungen aus, einschließlich, aber nicht beschränkt auf Marktgängigkeit und Eignung für einen bestimmten Zweck.</p><h3 id="haftungsbeschrankung" tabindex="-1">Haftungsbeschränkung <a class="header-anchor" href="#haftungsbeschrankung" aria-label="Permalink to &quot;Haftungsbeschränkung&quot;">​</a></h3><p>Der Entwickler haftet in keinem Fall für indirekte, zufällige, besondere, Folge- oder Strafschäden, die aus der Nutzung der App entstehen oder damit zusammenhängen.</p><h2 id="geistiges-eigentum" tabindex="-1">Geistiges Eigentum <a class="header-anchor" href="#geistiges-eigentum" aria-label="Permalink to &quot;Geistiges Eigentum&quot;">​</a></h2><p>Nicasa und die zugehörigen Marken sind Eigentum des Entwicklers. Code und Design der App sind urheberrechtlich geschützt.</p><h2 id="kundigung" tabindex="-1">Kündigung <a class="header-anchor" href="#kundigung" aria-label="Permalink to &quot;Kündigung&quot;">​</a></h2><p>Diese Bedingungen gelten bis zu ihrer Beendigung. Deine Rechte aus diesen Bedingungen enden automatisch, wenn du gegen eine dieser Bedingungen verstößt.</p><h2 id="anwendbares-recht" tabindex="-1">Anwendbares Recht <a class="header-anchor" href="#anwendbares-recht" aria-label="Permalink to &quot;Anwendbares Recht&quot;">​</a></h2><p>Diese Bedingungen unterliegen dem Recht der jeweils anwendbaren Jurisdiktionen und werden nach diesem ausgelegt, ohne Rücksicht auf Kollisionsnormen.</p><h2 id="anderungen-der-bedingungen" tabindex="-1">Änderungen der Bedingungen <a class="header-anchor" href="#anderungen-der-bedingungen" aria-label="Permalink to &quot;Änderungen der Bedingungen&quot;">​</a></h2><p>Der Entwickler behält sich das Recht vor, diese Bedingungen jederzeit zu ändern. Die weitere Nutzung der App nach Änderungen gilt als Annahme der neuen Bedingungen.</p><h2 id="kontaktinformationen" tabindex="-1">Kontaktinformationen <a class="header-anchor" href="#kontaktinformationen" aria-label="Permalink to &quot;Kontaktinformationen&quot;">​</a></h2><p>Bei Fragen zu diesen Bedingungen kontaktiere uns über das <a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">GitHub-Repository</a>.</p><p><em>Zuletzt aktualisiert: 16. April 2026</em></p>',32)])])}const b=n(t,[["render",u]]);export{c as __pageData,b as default};
